import { useState, useId, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxInput,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

type Role = 'viewer' | 'editor' | 'admin';

const ROLE_OPTIONS: { value: Role; label: string }[] = [
  { value: 'viewer', label: 'Наблюдатель' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const hintId = useId();
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState<Role>('editor');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const emailIsValid = EMAIL_PATTERN.test(email.trim());
  const showError = touched && !emailIsValid;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTouched(true);
    if (!emailIsValid) return;

    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
  }

  return (
    <div
      className="jx-stack"
      style={{ gap: 'var(--jx-space-4)', maxWidth: 'var(--jx-size-md)' }}
    >
      {invitedEmail && (
        <JxAlert
          variant="success"
          title="Приглашение отправлено"
          dismissible
          onClose={() => setInvitedEmail(null)}
        >
          {invitedEmail} получит доступ к команде.
        </JxAlert>
      )}

      <form
        className="jx-stack"
        style={{ gap: 'var(--jx-space-4)' }}
        onSubmit={handleSubmit}
        noValidate
      >
        <JxInput
          type="email"
          name="email"
          label="Рабочая почта"
          placeholder="name@company.com"
          value={email}
          onValueChange={setEmail}
          onBlur={() => setTouched(true)}
          invalid={showError}
          aria-describedby={hintId}
          hint="Приглашение придёт на этот адрес и будет действовать 7 дней."
          error={showError ? 'Введите адрес в формате name@company.com' : undefined}
        />

        <JxSelect
          name="role"
          label="Роль в команде"
          value={role}
          onValueChange={(next: string) => setRole(next as Role)}
          options={ROLE_OPTIONS}
        />

        <JxSwitch
          name="notify"
          label="Отправить уведомление"
          checked={notify}
          onCheckedChange={setNotify}
        />

        <JxButton type="submit" variant="primary" disabled={!emailIsValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

